  }]]},{move_to={ -2.975464, 0.100002, -4.339203 }, json=[[{"GUID": "dbe57b","Name": "Custom_Tile","Transform": {"posX": -26.5950851,"posY": 1.63850355,"posZ": 67.6321259,"rotX": 0.016917605,"rotY": 179.954987,"rotZ": 0.0798723,"scaleX": 9.106583,"scaleY": 1.0,"scaleZ": 9.106583},"Nickname": "","Description": "","GMNotes": "","ColorDiffuse": {"r": 0.9019608,"g": 0.168625,"b": 0.168625},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": true,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomImage": {"ImageURL": "https://cdn.jsdelivr.net/gh/mrdrouf/root-tabletop-tournament@main/assets/board/rats_board_mood_v3.png","ImageSecondaryURL": "https://steamusercontent-a.akamaihd.net/ugc/1744573560572486403/BA79EAB0896609D4FE2FF2211A7B866AEDD515B2/","ImageScalar": 1.0,"WidthScale": 0.0,"CustomTile": {"Type": 0,"Thickness": 0.2,"Stackable": false,"Stretch": true}},"LuaScript": "-- The Mini-Mood Manager is PRINTED on this board. It used to be a separate tile stacked on top,\n-- carrying both the snap points and this behaviour; the snaps are now baked into this board's\n-- AttachedSnapPoints and the behaviour lives here. Ported from the tool's own script, with the zone\n-- placed from the printed panel's position in THIS board's local frame, so it follows the board to\n-- any seat and any rotation instead of being read off a separate object's transform.\nlocal PANEL_LOCAL   = { x = -0.6581, y = 0.19, z = 0.5303 }\nlocal CARD_BIG      = 2.36\nlocal CARD_SMALL    = 0.57\nlocal ZONE_SCALE    = { x = 1, y = 12, z = 4 }\n\nlocal _zone     = nil\nlocal pickedUp  = false\n\nfunction onLoad(save_state)\n  createZone()\n  -- the faction spawn sets the board's rotation AFTER it lands, and a scripted setRotation does not\n  -- fire onRotate, so re-place the zone a few times while the board settles\n  Wait.time(resetZone, 0.3)\n  Wait.time(resetZone, 1.5)\n  Wait.time(resetZone, 3.0)\nend\n\nfunction onPickUp(player_color) _zone = nil pickedUp = true end\n\nfunction onDrop(player_color)\n  if _zone == nil then createZone() end\n  Wait.time(resetZone, 0.3)\n  pickedUp = false\nend\n\nfunction onRotate()\n  if _zone == nil and pickedUp == false then createZone() end\n  Wait.time(resetZone, 0.3)\nend\n\nlocal function isMoodCard(o)\n  return o ~= nil and o.tag == \"Card\" and o.hasTag(\"Rat Mood\")\nend\n\nfunction onObjectEnterScriptingZone(zone, enterObject)\n  if zone == _zone and isMoodCard(enterObject) then\n    enterObject.setScale({ x = CARD_BIG, y = 1, z = CARD_BIG })\n  end\nend\n\nfunction onObjectLeaveScriptingZone(zone, leaveObject)\n  if zone == _zone and isMoodCard(leaveObject) then\n    leaveObject.setScale({ x = CARD_SMALL, y = 1, z = CARD_SMALL })\n  end\nend\n\nfunction createZone()\n  local zoneName = self.getGUID() .. \" MOOD ZONE\"\n  for _, o in ipairs(getAllObjects()) do\n    if o.tag == \"Scripting\" and o.getName() == zoneName then _zone = o return end\n  end\n  _zone = spawnObject({\n    type         = \"ScriptingTrigger\",\n    position     = self.positionToWorld(PANEL_LOCAL),\n    rotation     = self.getRotation(),\n    sound        = false,\n    snap_to_grid = false,\n  })\n  _zone.setName(zoneName)\n  -- the tile leaked its zone on teardown; tagging it means a new game sweeps it with the faction\n  pcall(function() _zone.addTag(\"RTT Faction\") end)\nend\n\nfunction resetZone()\n  if _zone == nil then return end\n  _zone.setPosition(self.positionToWorld(PANEL_LOCAL))\n  _zone.setRotation(self.getRotation())\n  _zone.setScale(ZONE_SCALE)\nend\n","LuaScriptState": "","XmlUI": "","AttachedSnapPoints": [{"Position": {"x": -0.476329625,"y": 0.199932486,"z": -0.272212625},"Rotation": {"x": -6.73067143e-06,"y": 0.04047575,"z": 2.32548859e-06}},{"Position": {"x": -0.474906,"y": 0.200149059,"z": -0.0955988},"Rotation": {"x": -9.469037e-06,"y": 0.0405303948,"z": 3.63852928e-06}},{"Position": {"x": -0.6624085,"y": 0.200423315,"z": -0.09276913},"Rotation": {"x": -7.00019064e-06,"y": 0.0402708426,"z": 2.63223228e-06}},{"Position": {"x": -0.663835645,"y": 0.200035051,"z": -0.270829767},"Rotation": {"x": -9.570433e-06,"y": 0.0403801277,"z": 3.87862246e-06}},{"Position": {"x": -0.849882364,"y": 0.2004471,"z": -0.2708915},"Rotation": {"x": -9.529719e-06,"y": 0.04040745,"z": 3.858631e-06}},{"Position": {"x": -0.8498903,"y": 0.200284988,"z": -0.09573655},"Rotation": {"x": -6.982918e-06,"y": 0.04048941,"z": 2.46547188e-06}},{"Position": {"x": -1.03883708,"y": 0.200665146,"z": -0.0958113745},"Rotation": {"x": -6.93364245e-06,"y": 0.0405577123,"z": 2.52551649e-06}},{"Position": {"x": -1.03882849,"y": 0.200060472,"z": -0.270965874},"Rotation": {"x": -7.32013041e-06,"y": 0.0402162,"z": 3.06568018e-06}},{"Position": {"x": -0.6550015,"y": 0.199396074,"z": 0.5233629},"Rotation": {"x": -2.77927342e-07,"y": -0.003497057,"z": 4.00214873e-07}},{"Position": {"x": -0.2793,"y": 0.2,"z": 0.2257}},{"Position": {"x": -0.2804,"y": 0.2,"z": 0.4283}},{"Position": {"x": -0.2801,"y": 0.2,"z": 0.631}},{"Position": {"x": -0.2798,"y": 0.2,"z": 0.8336}},{"Position": {"x": -0.6582,"y": 0.2,"z": 0.5311}},{"Position": {"x": -1.0319,"y": 0.2,"z": 0.6306}},{"Position": {"x": -1.0317,"y": 0.2,"z": 0.4264}},{"Position": {"x": -1.0325,"y": 0.2,"z": 0.2268}},{"Position": {"x": -1.036,"y": 0.2,"z": 0.8317}}]}]]},{move_to={ 12.021253, 0.923549, 7.522959 }, json=[[{"GUID": "c305e4","Name": "Custom_Dice","Transform": {"posX": -11.5986042,"posY": 2.44463778,"posZ": 79.49578,"rotX": 26.5502262,"rotY": 1.50576091,"rotZ": 71.91002,"scaleX": 1.94999933,"scaleY": 1.94999933,"scaleZ": 1.94999933},"Nickname": "","Description": "","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 1.0,"b": 1.0},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": false,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": false,"Tooltip": true,"GridProjection