e id=\"13\" image=\"silver\" color=\"rgba(1, 1, 1, 1)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n      <Image id=\"14\" image=\"silver\" color=\"rgba(1, 1, 1, 1)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n      <Image id=\"15\" image=\"silver\" color=\"rgba(1, 1, 1, 1)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n\t</VerticalLayout>\r\n    <VerticalLayout spacing =\"1\">\r\n\t  <Image id=\"16\" image=\"bronze\" color=\"rgba(1, 1, 1, 1)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n      <Image id=\"17\" image=\"bronze\" color=\"rgba(1, 1, 1, 1)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n      <Image id=\"18\" image=\"bronze\" color=\"rgba(1, 1, 1, 1)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n\t</VerticalLayout>\r\n  </VerticalLayout>\r\n</Panel>\r\n<Panel id=\"ministers\" width=\"224\" Height=\"196\" position=\"-11 0 -20\" rotation=\"0 0 180\" padding=\"2 2 2 2\">\r\n  <VerticalLayout childForceExpandHeight=\"False\">\r\n    <VerticalLayout spacing =\"2\">\r\n      <HorizontalLayout spacing=\"4\">\r\n        <Image id=\"1\" image=\"Baron\" color=\"rgba(1, 1, 1, 0)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n        <Image id=\"2\" image=\"Duchess\" color=\"rgba(1, 1, 1, 0)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n        <Image id=\"3\" image=\"Earl\" color=\"rgba(1, 1, 1, 0)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n      </HorizontalLayout>\r\n      <HorizontalLayout spacing=\"4\">\r\n        <Image id=\"4\" image=\"Mayor\" color=\"rgba(1, 1, 1, 0)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n        <Image id=\"5\" image=\"Brig\" color=\"rgba(1, 1, 1, 0)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n        <Image id=\"6\" image=\"Banker\" color=\"rgba(1, 1, 1, 0)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n      </HorizontalLayout>\r\n      <HorizontalLayout spacing=\"4\">\r\n        <Image id=\"7\" image=\"Captain\" color=\"rgba(1, 1, 1, 0)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n        <Image id=\"8\" image=\"Foremole\" color=\"rgba(1, 1, 1, 0)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n        <Image id=\"9\" image=\"Marshal\" color=\"rgba(1, 1, 1, 0)\" preserveAspect=\"True\" onClick=\"toggle_image_alpha\"/>\r\n      </HorizontalLayout>\r\n    </VerticalLayout>\r\n  </VerticalLayout>\r\n</Panel>\r\n\r\n<!-- include molemonger.xml -->","CustomUIAssets": [{"Name": "Baron","URL": "https://steamusercontent-a.akamaihd.net/ugc/1760320391475423867/69D932088AD10999D15321E5FC7D749D4D19DDF2/"},{"Name": "Brig","URL": "https://steamusercontent-a.akamaihd.net/ugc/1760320391475424478/EDE13004C4D89E4BCA9FB6EB868015AD16210051/"},{"Name": "Captain","URL": "https://steamusercontent-a.akamaihd.net/ugc/1760320391475426497/9C4EE730A93BF4C1257A685651D783FA085EE09F/"},{"Name": "Duchess","URL": "https://steamusercontent-a.akamaihd.net/ugc/1760320391475427122/F6333B49410EFF640CDA3E0E502D8EF09727BA75/"},{"Name": "Earl","URL": "https://steamusercontent-a.akamaihd.net/ugc/1760320391475427917/F44235B0B8CBA6ED38B30A7D18D85104FC03A1DE/"},{"Name": "Foremole","URL": "https://steamusercontent-a.akamaihd.net/ugc/1760320391475428537/2656EA0BE1CA8287B9F72A86FBC8409619375609/"},{"Name": "Marshal","URL": "https://steamusercontent-a.akamaihd.net/ugc/1760320391475430033/1655D7CB8E41607EB9B712C7774E90DC53AAFFDF/"},{"Name": "Mayor","URL": "https://steamusercontent-a.akamaihd.net/ugc/1760320391475430776/2073AAEDE357EF4F76222125450239F46878987D/"},{"Name": "gold","URL": "https://steamusercontent-a.akamaihd.net/ugc/1760320391475429227/FC8F2AE8B4B394E9EA265A0AE780526A7640D9A1/"},{"Name": "bronze","URL": "https://steamusercontent-a.akamaihd.net/ugc/1760320391475425216/F606BC914F50EE0EE82E583C5F7910C3407650AB/"},{"Name": "silver","URL": "https://steamusercontent-a.akamaihd.net/ugc/1760320391475431372/ABC388B5C