EVERYTHING['Decks']['Refill Card'] = {color='', data={
  {move_to={ -0.015248, 0.214143, -5.746479 }, json=[[{"GUID": "aa1464","Name": "Custom_Token","Transform": {"posX": 92.0,"posY": 35.82524,"posZ": -56.84,"rotX": 0.01763774,"rotY": 180.0,"rotZ": 0.0801314,"scaleX": 3.38,"scaleY": 1.0,"scaleZ": 3.38},"Nickname": "","Description": "","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 1.0,"b": 1.0},"Tags": ["Deck Object"],"LayoutGroupSortIndex": 0,"Value": 0,"Locked": true,"Grid": true,"Snap": false,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomImage": {"ImageURL": "https://steamusercontent-a.akamaihd.net/ugc/792008635622436482/5F66602DA4FC363CCFED7A59E8542298BC2C2D2A/","ImageSecondaryURL": "","ImageScalar": 1.0,"WidthScale": 0.0,"CustomToken": {"Thickness": 0.200000152,"MergeDistancePixels": 8.333335,"StandUp": false,"Stackable": false}},"LuaScript":  "-- object IDs\r\nlocal THE_POND = \"347917\"\r\nlocal LIZARD_WIZARD = \"dc029b\"\r\nlocal LIZARD_BOARD = \"6a1fe4\"\r\nlocal VULTURE_BOARD = \"b29092\"\r\n\r\n-- location to place cards on\r\nlocal thePondLoc = {0.0,1.00,-0.09}\r\nlocal vultureBoardLoc = {-0.905,1.00,0.485}\r\nlocal lizardBoardLoc = {-0.905,1.00,0.5}\r\nlocal lizardWizardLoc = {0.484,1.00,-0.01}\r\n-- locations of positions on the deck holder\r\nlocal pos_discard     = {-0.957, 0.178, 0.222}\r\nlocal pos_discard_top = {-0.957, 1.00, 0.222}\r\nlocal pos_draw        = {0.957, 0.178, 0.222}\r\n--This is which way is face down for a card or deck relative to the tool\r\nlocal rot_offset = {x=0, y=0, z=180}\r\n\r\n-- dom positions - global\r\nlocal foxPosition         = {-41.88,11.69,-10.02}\r\nlocal rabbitPosition      = {-41.88,11.68, -3.39}\r\nlocal mousePosition       = {-41.88,11.68,  3.27}\r\nlocal birdPosition        = {-41.88,11.68,  9.91}\r\nlocal abominationPosition = {-41.88,11.68, 16.55}\r\n\r\n-- cards to add suit to name\r\nlocal function isASuitedCard(n)\r\n  return n == \"Dominance\"\r\n      or n == \"Root Tea\"\r\n      or n == \"Ambush\"\r\n      or n == \"Travel Gear\"\r\n      or n == \"Crossbow\"\r\nend\r\n\r\n-- cards that get shuffled into the deck on discard\r\n-- TODO: can we find a way to make this work with fan decks?\r\nlocal function isShuffleOnDiscard(n)\r\n  return n == \"Woodland Militias\"\r\n      or n == \"Council Spy\"\r\n      or n == \"Zealous Knights\"\r\n      or n == \"Rangersx\"\r\nend\r\n\r\n-- checks if the card is a dominance card\r\nlocal function isDominance(cardName)\r\n  return string.match(cardName, \"Dominance$\")\r\nend\r\n\r\n-- Finds all objects near the given point, used to shuffle decks and return dom cards\r\nlocal function findObjectsAtPosition(localPos)\r\n  --We convert that local position to a global table position\r\n  local globalPos = localPos\r\n  --We then do a raycast of a sphere on that position to find objects there\r\n  --It returns a list of hits which includes references to what it hit\r\n  local objList = Physics.cast({\r\n    origin=globalPos, --Where the cast takes place\r\n    direction={0,1,0}, --Which direction it moves (up is shown)\r\n    type=2, --Type. 2 is \"sphere\"\r\n    size={2,2,2}, --How large that sphere is\r\n    max_distance=1, --How far it moves. Just a little bit\r\n    debug=false --If it displays the sphere when casting.\r\n  })\r\n\r\n  --Now we have objList which contains any and all objects in that area.\r\n  --But we only want decks and cards. So we will create a new list\r\n  local decksAndCards = {}\r\n  --Then go through objList adding any decks/cards to our new list\r\n  for _, obj in ipairs(objList) do\r\n    if obj.hit_object.tag == \"Deck\" or obj.hit_object.tag == \"Card\" then\r\n      table.insert(decksAndCards, obj.hit_object)\r\n    end\r\n  end\r\n\r\n  --Now we return this to where it was called with the information\r\n  return decksAndCards\r\nend\r\n\r\n--Activated by a timer to shuffle deck\r\nfunction timer_shuffle()\r\n  --This uses our findObjects function to find the deck in in the draw area\r\n  local discardItemList = findObjectsAtPosition(self.positionToWorld(pos_draw))\r\n  --We should only have 1 item here, and it should be a deck\r\n  --But just in case, we will go through any and all returns\r\n  for _, obj in ipairs(discardItemList) do\r\n    --Final check to make sure its a deck we're trying to shuffle\r\n    if obj.tag == \"Deck\" then\r\n      obj.shuffle()\r\n    end\r\n  end\r\nend\r\n\r\n-- queues deck shuffling\r\nlocal function shuffleDeckLater()\r\n  Timer.destroy(\"shuffleTimer_\"..self.getGUID())\r\n  Timer.create({\r\n    identifier = \"shuffleTimer_\"..self.getGUID(),\r\n    function_name = \"timer_shuffle\",\r\n    function_owner = self,\r\n    delay = 1\r\n  })\r\nend\r\n\r\n-- sends a card to the given location and rotation with a delay on rotation\r\nlocal function sendCardTo(card, pos, rot)\r\n  local nearby = { x = pos.x * 0.8, y = pos.y + 5, z = pos.z * 0.8 }\r\n  card.setPosition(nearby)\r\n  card.setRotation(rot)\r\n  card.setPosition(pos)\r\nend\r\n\r\n-- returns for sendCardHome\r\nlocal NEEDS_SHUFFLE = 2\r\nlocal MOVED_CARD = 1\r\nlocal NO_MOVE = 0\r\n\r\n-- sends a card object to it's home, returns true if the object is home\r\nlocal function sendCardHome(card, thePond, isDiscard)\r\n  local description = card.getDescription():lower()\r\n  local isFrog = thePond ~= nil and description == \"frog\"\r\n\r\n  -- only send dom home if requested, though frog overrides that\r\n  if (isDiscard or isFrog) then\r\n    local name = card.getName()\r\n    -- some cards are shuffled into the deck on discard\r\n    if isShuffleOnDiscard(name) then\r\n      local rot = self.getRotation()\r\n      sendCardTo(card, self.positionToWorld(pos_draw), {\r\n        x=rot.x+rot_offset.x,\r\n        y=rot.y+rot_offset.y,\r\n        z=rot.z+rot_offset.z\r\n      })\r\n      return NEEDS_SHUFFLE\r\n      \r\n    elseif isDominance(name) then\r\n      if description == \"fox\" then\r\n        card.setPositionSmooth(foxPosition)\r\n      elseif description == \"rabbit\" then\r\n        card.setPositionSmooth(rabbitPosition)\r\n      elseif description == \"mouse\" then\r\n        card.setPositionSmooth(mousePosition)\r\n      elseif description == \"bird\" then\r\n        card.setPositionSmooth(birdPosition)\r\n      else\r\n        card.setPositionSmooth(abominationPosition)\r\n      end\r\n      Wait.frames(\r\n        function()\r\n            card.setRotationSmooth({0,90,0})\r\n        end,\r\n        10\r\n      )\r\n      return MOVED_CARD\r\n    end\r\n  end\r\n  -- frogs always get sent home if we have a pond\r\n  if isFrog then\r\n    sendCardTo(card, thePond.positionToWorld(thePondLoc), thePond.getRotation())\r\n    return MOVED_CARD\r\n  end\r\n  -- none of the above\r\n  return NO_MOVE\r\nend\r\n\r\n-- sends all cards in the deck to their homes\r\nlocal function sendDeckHome(item, thePond, isDiscard)\r\n  local offset = 0\r\n  local needsShuffle = false\r\n  for _, c in ipairs(item.getObjects()) do\r\n    -- only remove the card if we know it has a home\r\n    -- means either we are discarding and its dom/special, or its a frog\r\n    if (isDiscard and (isShuffleOnDiscard(c.name) or isDominance(c.name)))\r\n        or (thePond ~= nil and c.description:lower() == \"frog\") then\r\n      local card = item.takeObject({index = c.index + offset})\r\n      offset = offset - 1\r\n      if sendCardHome(card, thePond, isDiscard) == NEEDS_SHUFFLE then\r\n        needsShuffle = true\r\n      end\r\n    end\r\n  end\r\n  return needsShuffle\r\nend\r\n\r\n-- sends all cards at the location home\r\nlocal function sendCardsAtLocationHome(location, thePond, dominance)\r\n  local items = findObjectsAtPosition(location)\r\n  local needsShuffle = false\r\n  for _, item in ipairs(items) do\r\n    if item.name == \"Card\" then\r\n      if sendCardHome(item, thePond, dominance) == NEEDS_SHUFFLE then\r\n        needsShuffle = true\r\n      end\r\n    elseif item.name == \"Deck\" then\r\n      if sendDeckHome(item, thePond, dominance) then\r\n        needsShuffle = true\r\n      end\r\n    end\r\n  end\r\n  return needsShuffle\r\nend\r\n\r\n-- send a card from the pond to its proper home\r\nlocal function sendPondCardHome(card, discard, discardLoc)\r\n  local description = card.getDescription():lower()\r\n  -- remove non-frogs from the pond\r\n  if description ~= \"frog\" then\r\n    sendCardTo(card, discard.positionToWorld(discardLoc), discard.getRotation())\r\n    \r\n  -- send frog dom to frog dom location\r\n  elseif isDominance(card.getName()) then\r\n    card.setPositionSmooth(abominationPosition)\r\n    Wait.frames(\r\n      function()\r\n          card.setRotationSmooth({0,90,0})\r\n      end,\r\n      10\r\n    )\r\n  end\r\nend\r\n\r\n-- called when an object is placed on the mat to send dom/frog home\r\nfunction updateButtons()\r\n  -- need the pond for pulling out frog cards\r\n  local thePond = getObjectFromGUID(THE_POND)\r\n  \r\n  -- send the discard to dom and frog\r\n  local discard = self\r\n  local discardLoc = pos_discard\r\n  local needsShuffle = false\r\n  \r\n  -- send vultures to dom and frog\r\n  local vultureBoard = getObjectFromGUID(VULTURE_BOARD)\r\n  if vultureBoard ~= nil then\r\n    discard = vultureBoard\r\n    discardLoc = vultureBoardLoc\r\n    if sendCardsAtLocationHome(vultureBoard.positionToWorld(vultureBoardLoc), thePond, true) then\r\n      needsShuffle = true\r\n    end\r\n  else\r\n    -- skip regular discard if vultures are involved\r\n    if sendCardsAtLocationHome(self.positionToWorld(pos_discard), thePond, true) then\r\n      needsShuffle = true\r\n    end\r\n  end\r\n  \r\n  -- process the pond\r\n  if thePond ~= nil then\r\n    -- if pond and lizard wizard, send frog cards at the wizard to the pond\r\n    local lizardWizard = getObjectFromGUID(LIZARD_WIZARD)\r\n    if lizardWizard ~= nil then\r\n      discard = lizardWizard\r\n      discardLoc = lizardWizardLoc\r\n      sendCardsAtLocationHome(lizardWizard.positionToWorld(lizardWizardLoc), thePond, false)\r\n    else\r\n      lizardWizard = getObjectFromGUID(LIZARD_BOARD)\r\n      if lizardWizard ~= nil then\r\n        discard = lizardWizard\r\n        discardLoc = lizardBoardLoc\r\n        sendCardsAtLocationHome(lizardWizard.positionToWorld(lizardBoardLoc), thePond, false)\r\n      end\r\n    end\r\n    \r\n    -- purge non-frogs and frog dom from the pond\r\n    local items = findObjectsAtPosition(thePond.positionToWorld(thePondLoc))\r\n    for _, item in ipairs(items) do\r\n      if item.name == \"Card\" then\r\n        sendPondCardHome(item, discard, discardLoc)\r\n      elseif item.name == \"Deck\" then\r\n        local offset = 0\r\n        for _, c in ipairs(item.getObjects()) do\r\n          if isDominance(c.name) or c.description:lower() ~= \"frog\" then\r\n            local card = item.takeObject({index = c.index + offset})\r\n            offset = offset - 1\r\n            sendPondCardHome(card, discard, discardLoc)\r\n          end\r\n        end\r\n      end\r\n    end\r\n  end\r\n  \r\n  -- shuffle deck if requested\r\n  if needsShuffle then\r\n    shuffleDeckLater()\r\n  end\r\nend\r\n\r\nfunction onDestroy()\r\n   Wait.stop(wait_id)\r\nend\r\n\r\n--Creates invisible button onload, hidden under the \"REFILL\" on the deck pad\r\nfunction onLoad()\r\n  self.createButton({\r\n    click_function=\"click_refillDeck\", function_owner=self,\r\n    position={0,0.1,-1.12}, height=200, width=620, color={1,1,1,0}\r\n  })\r\n\r\n  --This is how I found the positions to check for cards\r\n  --That GUID was a card I put on it\r\n  --local pos = self.positionToLocal(getObjectFromGUID(\"a6b1bd\").getPosition())\r\n  --print(pos.x)\r\n  --print(pos.y)\r\n  --print(pos.z)\r\n\r\n  --This is which way is face down for a card or deck relative to the tool\r\n  wait_id = Wait.time(updateButtons, 1, -1)\r\n\r\n  addHotkey(\"Discard Hotkey\", discardHotkey)\r\nend\r\n\r\n--Activates when button is clicked\r\nfunction click_refillDeck()\r\n  --This gets all decks and cards in the discard areas\r\n  \r\n  --This is where we want to put those discarded cards\r\n  local pos = self.positionToWorld(pos_draw)\r\n  --This is how we want the card rotated\r\n  local rot = self.getRotation()\r\n  rot = {rot.x+rot_offset.x, rot.y+rot_offset.y, rot.z+rot_offset.z}\r\n  \r\n  -- move cards in the discard\r\n  local discardItemList = findObjectsAtPosition(self.positionToWorld(pos_discard))\r\n  local movedCards = #discardItemList > 0\r\n  for _, obj in ipairs(discardItemList) do\r\n      obj.setPositionSmooth(pos, false, true)\r\n      obj.setRotationSmooth(rot)\r\n  end\r\n  \r\n  -- move cards in the pond\r\n  local thePond = getObjectFromGUID(THE_POND)\r\n  if thePond ~= nil then\r\n    discardItemList = findObjectsAtPosition(thePond.positionToWorld(thePondLoc))\r\n    if #discardItemList > 0 then\r\n      movedCards = true\r\n      for _, obj in ipairs(discardItemList) do\r\n          obj.setPositionSmooth(pos, false, true)\r\n          obj.setRotationSmooth(rot)\r\n      end\r\n    end\r\n  end\r\n  \r\n  -- move cards in the vulture board\r\n  local vultureBoard = getObjectFromGUID(VULTURE_BOARD)\r\n  if vultureBoard ~= nil then\r\n    discardItemList = findObjectsAtPosition(vultureBoard.positionToWorld(vultureBoardLoc))\r\n    if #discardItemList > 0 then\r\n      movedCards = true\r\n      for _, obj in ipairs(discardItemList) do\r\n          obj.setPositionSmooth(pos, false, true)\r\n          obj.setRotationSmooth(rot)\r\n      end\r\n    end\r\n  end\r\n\r\n  --We check if any cards were moved before we go to shuffle\r\n  if movedCards then\r\n    shuffleDeckLater()\r\n  end\r\nend\r\n\r\n-- sends all dom cards in the object home\r\nlocal function sendDominanceHome(card)\r\n  if card.tag == 'Card' then\r\n    local ret = sendCardHome(card, nil, true)\r\n    if ret == NEEDS_SHUFFLE then\r\n      shuffleDeckLater()\r\n    end\r\n    return ret ~= NO_MOVE\r\n  elseif card.tag == 'Deck' then\r\n    if sendDeckHome(card, nil, true) then\r\n      shuffleDeckLater()\r\n    end\r\n    return card.getQuantity() <= 0\r\n  end\r\n  return false\r\nend\r\n\r\n--Put cards on discard tile or lizard cult lost souls tile\r\nlocal function _discardCard(color, cardObject)\r\n  -- card name to display\r\n  local card_list = ''\r\n  \r\n  -- frog cards always go to the pond\r\n  local thePond = getObjectFromGUID(THE_POND)\r\n\r\n  -- single cards are easy, find its name and send it home if a frog\r\n  if cardObject.tag == 'Card' then\r\n    card_list = cardObject.getName()\r\n    if isASuitedCard(cardObject.getName()) then\r\n      card_list = card_list .. \" (\" .. cardObject.getDescription()..\")\" \r\n    end\r\n    -- send frog cards home if needed, skip dom as that may go to lost souls\r\n    if sendCardHome(cardObject, thePond, false) ~= NO_MOVE then\r\n      printToAll(\"Discarded Frog Card: \"..card_list, color)\r\n      return\r\n    end\r\n  \r\n  -- decks are annoying, remove all frogs from the deck\r\n  elseif cardObject.tag == 'Deck' then\r\n    local objects = cardObject.getObjects()\r\n    local t = {}\r\n    for index, card in ipairs(objects) do\r\n      table.insert(t, '| ' .. card.name .. ' ')\r\n      if isASuitedCard(card.name) then\r\n        table.insert(t, \" (\" .. card.description..\") \")\r\n      end\r\n    end\r\n    card_list = table.concat(t)\r\n    \r\n    -- if we have frog cards, send them home immediately\r\n    if thePond ~= nil then\r\n      -- may have moved a card that gets shuffled into the deck\r\n      if sendDeckHome(cardObject, thePond, false) then\r\n        shuffleDeckLater()\r\n      end\r\n      -- if it was only frog cards, we are done\r\n      if cardObject.getQuantity() <= 0 then\r\n        printToAll(\"Discarded Frog Cards: \"..card_list, color)\r\n        return\r\n      end\r\n    end\r\n  end\r\n\r\n  -- from this point on we have no frogs, but still may have dom to deal with\r\n\r\n  -- lizard wizard takes priority for cards\r\n  -- if no lizard wizard, the lizard board becomes the lizard wizard\r\n  local lizardWizard = getObjectFromGUID(LIZARD_WIZARD)\r\n  local lizardWizardPos = {}\r\n  local lizardWizardRot = {}\r\n  if (lizardWizard ~= nil) then\r\n    lizardWizardPos = lizardWizard.positionToWorld(lizardWizardLoc)\r\n    lizardWizardRot = lizardWizard.getRotation()\r\n  else\r\n    lizardWizard = getObjectFromGUID(LIZARD_BOARD)\r\n    if (lizardWizard ~= nil) then\r\n      lizardWizardPos = lizardWizard.positionToWorld(lizardBoardLoc)\r\n      lizardWizardRot = lizardWizard.getRotation()\r\n    end    \r\n  end\r\n\r\n  -- still use regular discard pos for no vulture\r\n  local discardPos = self.positionToWorld(pos_discard_top)\r\n  local discardRot = self.getRotation()\r\n\r\n  -- vulture board replaces regular discard\r\n  local vultureBoard = getObjectFromGUID(VULTURE_BOARD)\r\n  local vultureBoardPos = {}\r\n  local vultureBoardRot = {}\r\n  if (vultureBoard ~= nil) then\r\n    vultureBoardPos = vultureBoard.positionToWorld(vultureBoardLoc)\r\n    vultureBoardRot = vultureBoard.getRotation()\r\n  end\r\n\r\n  local cardPos = cardObject.getPosition()\r\n  local pos = {}\r\n  local rot = {}\r\n  \r\n  -- don't print if already at discard\r\n  local atDiscard = Vector.equals(cardPos, discardPos, 1)\r\n  -- don't send vulture to lizard wizard or print if already there\r\n  local atVulture = vultureBoard ~= nil and Vector.equals(cardPos, vultureBoardPos, 1)\r\n  \r\n  -- lizard wizard being present means send to lizard\r\n  if lizardWizard ~= nil then\r\n    -- if already at the lizard wizard, or at the proper discard, just redirect it to proper discard\r\n    if atDiscard or atVulture or Vector.equals(cardPos, lizardWizardPos, 1) then\r\n      -- vulture board being around means send to vulture\r\n      if vultureBoard ~= nil then\r\n        pos = vultureBoardPos\r\n        rot = vultureBoardRot\r\n        if not atVulture then\r\n          printToAll(\"Discarded Lost Souls to Warriors Wake: \"..card_list, color)\r\n        end\r\n      else\r\n        -- send to discard\r\n        pos = discardPos\r\n        rot = discardRot\r\n        if not atDiscard then\r\n          printToAll(\"Discarded Lost Souls: \"..card_list, color)\r\n        end\r\n      end\r\n      -- send all dom home\r\n      if sendDominanceHome(cardObject) then\r\n        return\r\n      end\r\n    else\r\n      -- send to lost souls\r\n      pos = lizardWizardPos\r\n      rot = lizardWizardRot\r\n      printToAll(\"Discarded to Lost Souls: \"..card_list, color)\r\n    end\r\n  \r\n  -- non-lost souls\r\n  else\r\n    -- try vulture\r\n    if vultureBoard ~= nil then\r\n      pos = vultureBoardPos\r\n      rot = vultureBoardRot\r\n      if not atVulture then\r\n        printToAll(\"Discarded to Warriors Wake: \"..card_list, color)\r\n      end\r\n    \r\n    -- regular old discard\r\n    else\r\n      pos = discardPos\r\n      rot = discardRot\r\n      if not atDiscard then\r\n        printToAll(\"Discarded: \"..card_list, color)\r\n      end\r\n    end\r\n    \r\n    -- send all dom home after message\r\n    if sendDominanceHome(cardObject) then\r\n      return\r\n    end\r\n  end\r\n\r\n  -- move the actual card\r\n  sendCardTo(cardObject, pos, rot)\r\nend\r\n\r\n-- called when a new object is spawned to give it Spend/Discard\r\nfunction onObjectSpawn(object)\r\n  if not string.match(object.getGMNotes(), \"Quest\") then\r\n    if object.tag == 'Deck' or (object.tag == 'Card' and object.getDescription() ~= '') then\r\n      object.addContextMenuItem(\r\n        'Spend/Discard',\r\n        function(playerColor) _discardCard(playerColor, object) end,\r\n        false\r\n      )\r\n    end\r\n  end\r\nend\r\n\r\n-- called when the discard key is pressed\r\nfunction discardHotkey(player_color, hovered_object, world_position, key_down_up)\r\n  if not string.match(hovered_object.getDescription(), \"Quest\") then\r\n    if hovered_object.tag == 'Card' and hovered_object.getDescription() ~= '' then\r\n      _discardCard(player_color, hovered_object)\r\n    elseif hovered_object.tag == 'Deck' then\r\n      _discardCard(player_color, hovered_object)\r\n    end\r\n  end\r\nend\r\n","LuaScriptState": "","XmlUI": "","PhysicsMaterial": {"StaticFriction": 0.5,"DynamicFriction": 0.5,"Bounciness": 0.0,"FrictionCombine": 0,"BounceCombine": 0},"Rigidbody": {"Mass": 1.125,"Drag": 0.1,"AngularDrag": 0.1,"UseGravity": true},"AttachedSnapPoints": [{"Position": {"x": 0.959766865,"y": 0.102499925,"z": 0.208676264},"Rotation": {"x": -2.32625879E-07,"y": 359.900146,"z": 180.0}},{"Position": {"x": -0.9572971,"y": 0.102499895,"z": 0.2228536},"Rotation": {"x": -2.22738109E-07,"y": 359.975861,"z": 180.0}}]
