rotY": 45.91058,"rotZ": 170.4784,"scaleX": 2.299999,"scaleY": 2.299999,"scaleZ": 2.299999},"Nickname": "Infected Die","Description": "","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 1.0,"b": 1.0,"a": 0.894051969},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": false,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomImage": {"ImageURL": "https://steamusercontent-a.akamaihd.net/ugc/1789597400144292104/2B2AA16FBB77A831AACA784DA3D4F1AFCDA45D80/","ImageSecondaryURL": "","ImageScalar": 1.0,"WidthScale": 0.0,"CustomDice": {"Type": 1}},"LuaScript": "","LuaScriptState": "","XmlUI": "","RotationValues": [{"Value": "Rabbit","Rotation": {"x": -90.0,"y": 0.0,"z": 0.0}},{"Value": "Fox","Rotation": {"x": 0.0,"y": 0.0,"z": 0.0}},{"Value": "Mouse","Rotation": {"x": 0.0,"y": 0.0,"z": -90.0}},{"Value": "Mouse","Rotation": {"x": 0.0,"y": 0.0,"z": 90.0}},{"Value": "Fox","Rotation": {"x": 0.0,"y": 0.0,"z": -180.0}},{"Value": "Rabbit","Rotation": {"x": 90.0,"y": 0.0,"z": 0.0}}]}]
